import {makeCompanionContext} from '../../apps/web/lib/job-companion';
import React,{useState} from 'react';import {createRoot} from 'react-dom/client';import OwnerNetwork from '../../apps/web/app/owner-network';import OwnerNetworkLookup from '../../apps/web/app/owner-network-lookup';import {EntrySafety} from '../../apps/web/app/entry-safety';
const organization='20000000-0000-4000-8000-000000000001';
function Harness(){const [lookup,setLookup]=useState(false);const companion=new URL(location.href).searchParams.has('companion');const context=companion?makeCompanionContext({request:'41000000-0000-4000-8000-000000000001',customer:'Synthetic Neighbor',email:'neighbor@example.invalid',company:'Example Care',phase:'working',next:'Work in progress'}):undefined;return <EntrySafety><main className="company-workspace" style={{padding:'1rem'}}><label>Unfinished job note<textarea defaultValue="Preserve this private job draft"/></label><button onClick={()=>setLookup(true)}>Open support lookup</button><OwnerNetwork organization={organization}/>{lookup&&<OwnerNetworkLookup organization={organization} tasks={companion?['Smart lock installation','Shelf installation','Uncatalogued custom work']:['Smart lock installation']} context={context} initialView={companion?'learn':'refer'} onClose={()=>setLookup(false)}/>}</main></EntrySafety>;}
createRoot(document.getElementById('root')!).render(<Harness/>);
